# Extract each cell's content
def extract_cell(grid, row_start, row_end, col_start, col_end):
    return [[grid[r][c] for c in range(col_start, col_end)] for r in range(row_start, row_end)]

# Horizontal sections (between dividers and at edges)
sections_h = [(0,1), (3,4), (6,7), (9,10), (12,13), (15,16), (18,19)]
# Vertical sections (between dividers and at edges)
sections_v = [(0,4), (6,10), (12,16)]

cells = {}
for i, (rh, re) in enumerate(sections_h):
    for j, (cv, ce) in enumerate(sections_v):
        cell = extract_cell(grid, rh, re, cv, ce)
        # Find all non-zero, non-5 values
        content = []
        for r in range(len(cell)):
            for c in range(len(cell[r])):
                if cell[r][c] != 0 and cell[r][c] != 5:
                    content.append((cell[r][c], r, c))
        cells[(i,j)] = content

# Print the content of each cell
for i in range(len(sections_h)):
    row_str = " | ".join(f"({cells[(i,j)]})" for j in range(len(sections_v)))
    print(f"Row {i}: {row_str}")

# Print grid of cells with their contents
print("Cell grid (row, col) -> contents [(color, relative_row, relative_col)]:")
print("=" * 80)
for i in range(len(sections_h)):
    row_cells = []
    for j in range(len(sections_v)):
        key = (i, j)
        if key in cells:
            row_cells.append(f"{cells[key]}")
        else:
            row_cells.append("[]")
    print(f"Row {i}: {row_cells}")

# Map out each cell clearly
# Cells are indexed (row_sec, col_sec) where row_sec = 0-6, col_sec = 0-2

def get_cell_content(grid, r_start, r_end, c_start, c_end):
    content = []
    for r in range(r_start, r_end):
        for c in range(c_start, c_end):
            val = grid[r][c]
            if val != 0 and val != 5:
                content.append((val, r, c))
    return content

# Show the full cell grid
for rsec in range(7):
    r1 = 2*rsec
    if r1 < 20:
        print(f"\nRow section {rsec}:")
        for csec in range(3):
            if csec == 0:
                c1, c2 = 0, 5
            elif csec == 1:
                c1, c2 = 6, 11
            else:
                c1, c2 = 12, 17

            content = get_cell_content(grid, r1, r1+2, c1, c2)
            if content:
                print(f"  Cell ({rsec},{csec}) at grid rows {r1}-{r1+1}, cols {c1}-{c2-1}: {content}")
            else:
                print(f"  Cell ({rsec},{csec}): empty")

# Simplify the cell representation
# Store as (color, relative_row, relative_col) where relative is within the 2-row section

cells_simple = {}
for rsec in range(7):
    for csec in range(3):
        key = (rsec, csec)
        # Extract content again with this calculation
        content = []
        for r, c in [(rsec*2 + offset_row, csec*4 + offset_col) 
                     for offset_row in [0, 1] for offset_col in range(5)
                     if True]:
            pass

        # Let's just map cell by cell
        r1, r2 = sections_h[rsec][0], sections_h[rsec][1]
        c1, c2 = sections_v[csec][0], sections_v[csec][1]
        for r in range(r1, r2+1):
            for c in range(c1, c2):
                val = grid[r][c]
                if val != 0 and val != 5:
                    content.append((val, r-r1, c-c1))
        cells_simple[key] = content

# Print as a visual 7x3 grid
print("Cell contents (color, rel_row, rel_col):")
for rsec in range(7):
    row_str = " ".join(f"{cells_simple[(rsec,csec)]}" for csec in range(3))
    print(row_str)

